export function playRoulette(p) { const selectedColor = p.payload?.color; const selectedNumber = Number.isInteger(p.payload?.number) ? p.payload.number : undefined; const outside = p.payload?.outside; const number = Math.floor(Math.random() * 37); const color = number === 0 ? 'green' : number % 2 === 0 ? 'black' : 'red'; const numberBet = selectedNumber !== undefined && selectedNumber >= 0 && selectedNumber <= 36; let win = false; let multiplier = 2; let selected = selectedColor; let selectedType = 'color'; if (numberBet) { selectedType = 'number'; selected = selectedNumber; multiplier = 36; win = selectedNumber === number; } else if (outside) { selectedType = 'outside'; selected = outside; if (outside === 'first12') { win = number >= 1 && number <= 12; multiplier = 3; } else if (outside === 'second12') { win = number >= 13 && number <= 24; multiplier = 3; } else if (outside === 'third12') { win = number >= 25 && number <= 36; multiplier = 3; } else if (outside === 'low') { win = number >= 1 && number <= 18; } else if (outside === 'high') { win = number >= 19 && number <= 36; } else if (outside === 'even') { win = number !== 0 && number % 2 === 0; } else if (outside === 'odd') { win = number % 2 === 1; } else if (outside === 'row1') { win = [3, 6, 9, 12, 15, 18, 21, 24, 27, 30, 33, 36].includes(number); multiplier = 3; } else if (outside === 'row2') { win = [2, 5, 8, 11, 14, 17, 20, 23, 26, 29, 32, 35].includes(number); multiplier = 3; } else if (outside === 'row3') { win = [1, 4, 7, 10, 13, 16, 19, 22, 25, 28, 31, 34].includes(number); multiplier = 3; } } else { selectedType = 'color'; selected = selectedColor || 'red'; multiplier = color === 'green' ? 14 : 2; win = selected === color; } const winAmount = win ? p.betAmount * multiplier : 0; return { game: 'roulette', selected, selectedType, number, color, win, multiplier, winAmount }; }
